#!/bin/bash
# Cursor sessionStart hook — generated by scripts/gen-harness-cursor.ts, do not edit.
# Answers with `tea-rags prime <project>` as additional_context.
# sessionStart is fire-and-forget: a missing digest is covered by the core rule.
# Plugin hooks run in the plugin directory: the project comes from CURSOR_PROJECT_DIR or stdin, never $PWD.

INPUT=$(cat)
ROOT="${CURSOR_PROJECT_DIR:-}"
if [ -z "$ROOT" ]; then
  ROOT=$(printf '%s' "$INPUT" | jq -r '.workspace_roots[0] // empty' 2>/dev/null)
fi
if [ -z "$ROOT" ]; then
  echo '{}'
  exit 0
fi
BIN="${TEA_RAGS_BIN:-}"
if [ -z "$BIN" ]; then
  BIN=$(command -v tea-rags 2>/dev/null)
fi
if [ -z "$BIN" ]; then
  for CANDIDATE in "$HOME/.npm-global/bin/tea-rags" /opt/homebrew/bin/tea-rags /usr/local/bin/tea-rags; do
    if [ -x "$CANDIDATE" ]; then
      BIN="$CANDIDATE"
      break
    fi
  done
fi
DIGEST=""
if [ -n "$BIN" ]; then
  DIGEST=$("$BIN" prime "$ROOT" 2>/dev/null)
fi
if [ -z "$DIGEST" ]; then
  echo '{}'
  exit 0
fi
jq -n --arg context "$DIGEST" '{ additional_context: $context[0:10000] }' 2>/dev/null || echo '{}'
exit 0
